SourceCode.Declaration:
/// <summary>
/// Controller class for purchase order workflow submission batch processing.
/// </summary>
class METPurchTableWorkflowSubmissionBatchController extends SysOperationServiceController implements BatchRetryable
{
}

Method.Source:
/// <summary>
/// Specifies if the batch task is retryable for exceptions or not.
/// </summary>
/// <returns>
/// If true is returned, the batch task is retryable, otherwise it is not.
/// </returns>
[Hookable(false)]
final boolean isRetryable()
{
    return true;
}

/// <summary>
/// New method
/// </summary>
protected void new()
{
    super(classStr(METPurchTableWorkflowSubmissionBatchService), methodStr(METPurchTableWorkflowSubmissionBatchService, process), SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// Defines caption.
/// </summary>
/// <returns>Caption</returns>
public ClassDescription defaultCaption()
{
    return "Submit pruchase orders to workflow";
}

/// <summary>
/// Executes the batch job.
/// </summary>
/// <param name = "_args">
/// <c>Args</c>.
/// </param>
public static void main(Args _args)
{
    METPurchTableWorkflowSubmissionBatchController controller = new METPurchTableWorkflowSubmissionBatchController();
    controller.parmArgs(_args);
    controller.startOperation();
}
